/**
 * @name Path traversal in file operations
 * @description Untrusted input flowing to file operations can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Define file operation sinks using API graph
    exists(API::CallNode call |
      (
        // os.path.join - can be used to construct paths
        call = API::moduleImport("os.path").getMember("join").getACall() or
        // open function for file operations
        call = API::builtin("open").getACall() or
        // file() constructor in Python 2
        call = API::builtin("file").getACall() or
        // shutil file operations
        call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() or
        // os file operations
        call = API::moduleImport("os").getMember(["remove", "unlink", "rename", "mkdir", "makedirs"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

